<?php
/** Source-labelled warehouse. Upserts are exact source/kind/id, never fuzzy product matching. */
class AiHub {
    private $store;
    public const KINDS=['products'=>'products','inventory'=>'products','posts'=>'wp_crm','pages'=>'wp_crm','taxonomies'=>'wp_crm','sales'=>'sale_analysis','gsc'=>'seo_intel','ga4'=>'seo_intel'];
    public function __construct($store){$this->store=$store;}
    public static function canKind($kind,$mode='view'){if(!is_string($kind)||!isset(self::KINDS[$kind]))return false;if($kind==='gsc')return ModuleProjectAccess::allowed('seo_intel','analysis','seo_intel_keywords',$mode)&&ModuleProjectAccess::allowed('seo_intel','analysis','seo_intel_pages',$mode);if($kind==='ga4')return ModuleProjectAccess::allowed('seo_intel','analysis','seo_intel_traffic',$mode);return canAccessFeature(self::KINDS[$kind],$mode);}
    public static function need($kind,$mode='view'){if(!is_string($kind)||!isset(self::KINDS[$kind]))throw new RuntimeException('نوع منبع معتبر نیست.');if(!self::canKind($kind,$mode))throw new RuntimeException('دسترسی این منبع داده فعال نیست.');}
    public function createSource($project,$principal,$input){AiAccess::write();$kinds=$input['kinds']??[];if(!is_array($kinds)||!$kinds||array_diff($kinds,array_keys(self::KINDS)))throw new RuntimeException('نوع دادهٔ منبع را انتخاب کنید.');foreach($kinds as $k)self::need($k,'use');$name=trim($input['name']??'');$origin=trim($input['origin']??'');$storeId=trim($input['store_id']??'');if($name===''||$origin===''||$storeId===''||strlen($name)>200||strlen($origin)>300||strlen($storeId)>100)throw new RuntimeException('نام منبع، منشأ و شناسهٔ فروشگاه لازم است.');
        $transport=$input['transport']??'manual';if(!in_array($transport,['manual','wordpress','tiam','google','chatgpt','crm','composio'],true))throw new RuntimeException('روش اتصال منبع معتبر نیست.');$id=bin2hex(random_bytes(16));$token=bin2hex(random_bytes(32));$this->store->transaction(static function(&$s)use($id,$token,$name,$origin,$storeId,$kinds,$principal,$project,$transport){$s['hub_sources'][$id]=['id'=>$id,'project'=>$project['id'],'owner'=>$principal['owner'],'principal'=>$principal,'transport'=>$transport,'name'=>$name,'origin'=>$origin,'store_id'=>$storeId,'kinds'=>array_values(array_unique($kinds)),'token_hash'=>hash('sha256',$token),'enabled'=>true,'created'=>time()];});return ['id'=>$id,'token'=>$token];
    }
    public function source($project,$id){if(!is_string($id)||!preg_match('/^[a-f0-9]{32}$/D',$id))throw new RuntimeException('شناسهٔ منبع معتبر نیست.');$s=$this->store->read();$row=$s['hub_sources'][$id]??null;if(!$row||$row['project']!==$project['id'])throw new RuntimeException('منبع در پروژه یافت نشد.');return $row;}
    /** Switch adapters atomically; old workers cannot ingest under a new configuration. */
    public function configureAdapter($source,$adapter,$config){
        return $this->store->transaction(static function(&$s)use($source,$adapter,$config){
            $id=$source['id'];$current=$s['hub_sources'][$id]??null;
            if(!$current||!$current['enabled']||($current['revision']??null)!==($source['revision']??null))throw new RuntimeException('تنظیمات منبع تغییر کرده است؛ صفحه را تازه کنید.');
            foreach(['identity','google','composio'] as $old){$previous=$current[$old]??[];foreach(['site','property'] as $field)if(!empty($previous[$field])&&!empty($config[$field])&&$previous[$field]!==$config[$field]){
                foreach($s['hub_index']??[] as $key=>$rows)if(strpos($key,$id.':')===0&&$rows)throw new RuntimeException('برای سایت یا Property متفاوت، منبع جدید بسازید تا داده‌ها ترکیب نشوند.');
            }}
            foreach(['google','composio'] as $old)foreach(['site','property'] as $field)if(!empty($current[$old][$field]))$current['identity'][$field]=$current[$old][$field];foreach(['site','property'] as $field)if(!empty($config[$field]))$current['identity'][$field]=$config[$field];unset($current['google'],$current['composio']);$current[$adapter]=$config;$current['transport']=$adapter;$current['revision']=bin2hex(random_bytes(16));
            $s['hub_sources'][$id]=$current;unset($s['composio_sync'][$id]);foreach(array_keys($s['google_sync']??[]) as $key)if(strpos($key,$id.':')===0)unset($s['google_sync'][$key]);
            return $current['revision'];
        });
    }
    public function sources($project){$s=$this->store->read();$rows=[];foreach($s['hub_sources']??[] as $source)if($source['project']===$project['id']){$kinds=array_values(array_filter($source['kinds'],static fn($k)=>self::canKind($k,'view')));if(!$kinds)continue;$r=$source;$r['google_connected']=!empty($source['google']['refresh_token']);unset($r['principal'],$r['token_hash'],$r['google'],$r['composio']);$r['kinds']=$kinds;$rows[]=$r;}return $rows;}
    public function credentials($token){if(!is_string($token)||!preg_match('/^[a-f0-9]{64}$/D',$token))throw new RuntimeException('invalid_token');$s=$this->store->read();foreach($s['hub_sources']??[] as $source)if($source['enabled']&&hash_equals($source['token_hash'],hash('sha256',$token)))return $source;throw new RuntimeException('invalid_token');}
    public function disable($project,$principal,$id){$this->store->transaction(static function(&$s)use($project,$principal,$id){$r=&$s['hub_sources'][$id];if(!$r||$r['project']!==$project['id']||($r['owner']!==$principal['owner']&&!isMainAdmin()))throw new RuntimeException('مجوز تغییر منبع ندارید.');$r['enabled']=false;});}
    public function ingest($project,$source,$kind,$rows,$batch,$complete=false){
        self::need($kind,'use');AiAccess::write();if(!$source['enabled']||$source['project']!==$project['id']||!in_array($kind,$source['kinds'],true))throw new RuntimeException('منبع اجازهٔ این نوع داده را ندارد.');
        if(!is_string($batch)||!preg_match('/^[a-zA-Z0-9_.:-]{8,150}$/D',$batch)||!is_array($rows)||array_values($rows)!==$rows||!is_bool($complete)||count($rows)>1000||strlen(json_encode($rows))>4*1024*1024)throw new RuntimeException('بسته باید حداکثر ۱۰۰۰ ردیف و ۴ مگابایت باشد.');
        $normalized=[];$ids=[];foreach($rows as $row){$r=self::normalize($kind,$row,$source);if(isset($ids[$r['id']]))throw new RuntimeException('شناسهٔ تکراری داخل بسته است.');$ids[$r['id']]=true;$normalized[]=$r;}
        $hash=hash('sha256',json_encode([$kind,$normalized,$complete]));$receipt=hash('sha256',$source['id'].'|'.$batch);$doc=bin2hex(random_bytes(16));
        return $this->store->transaction(function(&$s)use($project,$source,$kind,$normalized,$receipt,$hash,$doc,$complete){
            $current=$s['hub_sources'][$source['id']]??null;if(!$current||!$current['enabled']||($current['revision']??null)!==($source['revision']??null))throw new RuntimeException('اتصال منبع لغو شده است.');
            if(isset($s['hub_batches'][$receipt])){if($s['hub_batches'][$receipt]['hash']!==$hash)throw new RuntimeException('شناسهٔ بسته با دادهٔ متفاوت تکرار شده است.');return $s['hub_batches'][$receipt]['result'];}
            $this->store->putDocument($project['id'],$doc,['rows'=>$normalized]);$key=$source['id'].':'.$kind;
            foreach($normalized as $i=>$r)$s['hub_index'][$key][hash('sha256',$r['id'])]=['doc'=>$doc,'offset'=>$i,'at'=>time()];
            $s['hub_sources'][$source['id']]['last_received'][$kind]=time();if($complete)$s['hub_sources'][$source['id']]['last_complete'][$kind]=time();
            $result=['accepted'=>count($normalized),'total'=>count($s['hub_index'][$key]??[]),'source'=>$source['id'],'kind'=>$kind,'complete'=>(bool)$complete];$s['hub_batches'][$receipt]=['hash'=>$hash,'result'=>$result,'project'=>$project['id'],'at'=>time()];return $result;
        });
    }
    public static function normalize($kind,$row,$source){
        if(!is_array($row)||(!is_string($row['id']??null)&&!is_int($row['id']??null))||trim((string)$row['id'])===''||strlen((string)$row['id'])>200)throw new RuntimeException('هر ردیف باید id ثابت از سیستم مبدأ داشته باشد.');
        $fields=['id','name','sku','url','status','modified_at','date','title','description','categories','images','stock','price','currency','parent_id','attributes','seo_title','seo_description','focus_keyword','canonical','robots','seo_score','permalink','type','grain','gross','refund','net','orders','quantity','clicks','impressions','ctr','position','page','query','country','device','sessions','active_users','conversions','revenue','store_id','taxonomy','term_id','slug','content_html','stock_status','short_description','tags','content_truncated','size_chart_url','version','in_latest_snapshot'];
        $out=array_intersect_key($row,array_flip($fields));$out['id']=(string)$row['id'];$out['store_id']=$source['store_id'];
        foreach($out as $k=>$v){if(is_string($v)&&mb_strlen($v)>30000)throw new RuntimeException('متن ردیف بیش از اندازه است.');if(!is_scalar($v)&&$v!==null&&!in_array($k,['categories','images','attributes','robots','tags'],true))throw new RuntimeException('ساختار ستون '.$k.' معتبر نیست.');}
        foreach(['stock','price','gross','refund','net','orders','quantity','clicks','impressions','ctr','position','sessions','active_users','conversions','revenue'] as $f)if(isset($out[$f])){if(!is_numeric($out[$f])||!is_finite((float)$out[$f])||abs((float)$out[$f])>1e15)throw new RuntimeException('مقدار عددی '.$f.' معتبر نیست.');$out[$f]=0+$out[$f];}
        if(in_array($kind,['sales','gsc','ga4'],true)&&(!is_string($out['date']??null)||!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$out['date'])||!checkdate((int)substr($out['date'],5,2),(int)substr($out['date'],8,2),(int)substr($out['date'],0,4))))throw new RuntimeException('تاریخ میلادی معتبر YYYY-MM-DD لازم است.');
        if($kind==='gsc'){foreach(['clicks','impressions','ctr','position'] as $f)if(!isset($out[$f])||$out[$f]<0)throw new RuntimeException('متریک معتبر سرچ کنسول لازم است: '.$f);if($out['ctr']>1)throw new RuntimeException('CTR باید نسبت صفر تا یک باشد.');}
        if($kind==='sales'){foreach(['gross','refund','net','orders'] as $f)if(!isset($out[$f]))throw new RuntimeException('ستون فروش '.$f.' لازم است.');if(!in_array($out['grain']??'',['order','day'],true)||!is_string($out['currency']??null)||!preg_match('/^[A-Z]{3}$/D',$out['currency']))throw new RuntimeException('واحد پول سه‌حرفی و grain برابر order یا day لازم است.');if($out['gross']<0||$out['refund']<0||$out['orders']<0||floor($out['orders'])!=$out['orders']||abs(($out['gross']-$out['refund'])-$out['net'])>0.01)throw new RuntimeException('خالص فروش با ناخالص منهای مرجوعی برابر نیست.');}
        if(strlen(json_encode($out))>100000)throw new RuntimeException('ردیف بیش از اندازه بزرگ است.');return $out;
    }
    public function read($project,$id,$kind,$filters=[],$offset=0,$limit=100){self::need($kind);foreach(['from','to'] as $f)if(isset($filters[$f])&&(!is_string($filters[$f])||!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$filters[$f])||!checkdate((int)substr($filters[$f],5,2),(int)substr($filters[$f],8,2),(int)substr($filters[$f],0,4))))throw new RuntimeException('تاریخ فیلتر باید YYYY-MM-DD باشد.');if(isset($filters['from'],$filters['to'])&&$filters['from']>$filters['to'])throw new RuntimeException('شروع بازه بعد از پایان است.');if(isset($filters['currency'])&&(!is_string($filters['currency'])||!preg_match('/^[A-Z]{3}$/D',$filters['currency'])))throw new RuntimeException('واحد پول فیلتر معتبر نیست.');if(isset($filters['grain'])&&!in_array($filters['grain'],['order','day'],true))throw new RuntimeException('سطح فروش فیلتر معتبر نیست.');$source=$this->source($project,$id);if(!in_array($kind,$source['kinds'],true))throw new RuntimeException('نوع داده متعلق به منبع نیست.');if(!is_int($offset)||$offset<0||!is_int($limit)||$limit<1||$limit>500)throw new RuntimeException('صفحهٔ دریافت معتبر نیست.');
        $s=$this->store->read();$index=$s['hub_index'][$id.':'.$kind]??[];$docs=[];$matched=[];$total=0;
        foreach($index as $ref){if(!isset($docs[$ref['doc']])){if(count($docs)>=8)$docs=[];$docs[$ref['doc']]=$this->store->document($project['id'],$ref['doc']);}$r=$docs[$ref['doc']]['rows'][$ref['offset']];if(!empty($filters['from'])&&($r['date']??'')<$filters['from']||!empty($filters['to'])&&($r['date']??'')>$filters['to']||!empty($filters['currency'])&&($r['currency']??'')!==$filters['currency']||!empty($filters['grain'])&&($r['grain']??'')!==$filters['grain'])continue;if($total>=$offset&&count($matched)<$limit)$matched[]=$r;$total++;}
        return ['source'=>'hub:'.$id.':'.$kind,'project_id'=>$project['id'],'name'=>$source['name'],'origin'=>$source['origin'],'store_id'=>$source['store_id'],'kind'=>$kind,'updated_at'=>$source['last_received'][$kind]??null,'last_complete'=>$source['last_complete'][$kind]??null,'total'=>$total,'offset'=>$offset,'next_offset'=>$offset+$limit<$total?$offset+$limit:null,'complete'=>$offset===0&&$total<=$limit,'rows'=>$matched];
    }
    public function stats($project,$id,$kind,$filters=[]){$totals=[];$count=0;$offset=0;$issues=['missing_seo_title'=>0,'missing_seo_description'=>0,'noindex'=>0,'missing_image'=>0];do{$page=$this->read($project,$id,$kind,$filters,$offset,500);foreach($page['rows'] as $r){$count++;if($kind==='sales'){if(in_array($r['status']??'',['cancelled','failed','pending','on-hold','checkout-draft','trash'],true))continue;$group=$r['currency'].'/'.$r['grain'];foreach(['gross','refund','net','orders'] as $f)$totals[$group][$f]=($totals[$group][$f]??0)+$r[$f];}elseif(in_array($kind,['products','posts','pages','taxonomies'],true)){if(empty($r['seo_title']))$issues['missing_seo_title']++;if(empty($r['seo_description']))$issues['missing_seo_description']++;if(strpos(json_encode($r['robots']??[]),'noindex')!==false)$issues['noindex']++;if(empty($r['images']))$issues['missing_image']++;}}$offset=$page['next_offset'];}while($offset!==null);return ['records'=>$count,'sales_by_currency_and_grain'=>$totals,'seo_issues'=>$issues,'warning'=>'Different sources and grains must not be summed together; sources may cover the same orders. SEO checks are metadata completeness checks, not a fabricated search ranking.'];}
}
